/// <reference types="vite/client" />

/**
 * Типы окружения Vite.
 *
 * Существует ради одной строки: `import.meta.env.DEV`.
 *
 * ─── Почему нужен отдельный файл, а не `vite/client` в `types` ───────────────
 *
 * `types` в `compilerOptions` подключает пакет для **всего проекта** как
 * глобальный, и `import.meta.env` в этом случае доступен. Но `App.tsx` лежит
 * рядом с `vite-env.d.ts` и не импортирует его: полагаться на подключение
 * «из типа» оказалось ненадёжным — без явной ссылки `tsc --noEmit` падал с
 * TS2339 «Property 'env' does not exist on type 'ImportMeta'», хотя `types`
 * в `tsconfig.json` был на месте.
 *
 * Тройной слеш — не комментарий, а директива TypeScript: именно так файл
 * объявляет, что ему нужны глобальные типы. Комментарий рядом объясняет,
 * почему директива тут, иначе её снесут как лишнюю.
 *
 * ─── Что этот файл даёт ──────────────────────────────────────────────────────
 *
 * `DEV` — режим разработки. Используется в `App.tsx` как условие ленивой
 * загрузки витрины компонентов: в сборке подставляется `false`, и вместе с
 * веткой выбрасывается модуль.
 */

/**
 * Расширение `ImportMetaEnv` из `vite/client`.
 *
 * Перечислено явно, чтобы опечатка в имени флага была ошибкой компиляции, а
 * не тихо равным `undefined` значением, которое выключило бы витрину и в
 * разработке тоже.
 */
interface ImportMetaEnv {
  readonly DEV: boolean;
  readonly PROD: boolean;
  readonly MODE: string;
  readonly BASE_URL: string;
}

/*
  `ImportMeta` объявлять НЕ нужно: он уже описан в `vite/client` и в `lib
  es2020`, и повторное объявление интерфейса с тем же именем слилось бы с
  существующим, а не заменило его. Проверено: `readonly env` в объявленном
  здесь интерфейсе конфликтует с `env: ImportMetaEnv` из `vite/client` по
  модификатору `readonly`, и `tsc` падает на redeclaration.

  Достаточно `/// <reference types="vite/client" />` в начале файла — он
  подключает и объявление `ImportMetaEnv`, и `ImportMeta`.
*/